        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(sc.next());
        }
        StringBuilder out = new StringBuilder();
        if (n == 1) {
            out.append(a[0]).append("\n");
        }
        for (int i = 1; i < n; i++) {
            int key = a[i];
            int j = i - 1;
            while (j >= 0 && a[j] > key) {
                a[j + 1] = a[j];
                j--;
            }
            a[j + 1] = key;
            out.append(join(a)).append("\n");
        }
        System.out.print(out);
    }
}

