    static int daysNeeded(int[] a, long capacity) {
        int days = 1;
        long load = 0;
        for (int w : a) {
            if (load + w > capacity) {
                days++;
                load = 0;
            }
            load += w;
        }
        return days;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        int d = Integer.parseInt(sc.next());
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(sc.next());
        }
        long low = 0;
        long high = 0;
        for (int w : a) {
            low = Math.max(low, w);
            high += w;
        }
        while (low < high) {
            long mid = (low + high) / 2;
            if (daysNeeded(a, mid) <= d) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        System.out.println(low);
    }
}

