        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(sc.next());
        }
        Random random = new Random(12345);
        int target = k - 1;
        int low = 0;
        int high = n - 1;
        int answer = 0;
        while (true) {
            int pivot = a[low + random.nextInt(high - low + 1)];
            int lt = low;
            int gt = high;
            int i = low;
            while (i <= gt) {
                if (a[i] < pivot) {
                    int t = a[lt];
                    a[lt] = a[i];
                    a[i] = t;
                    lt++;
                    i++;
                } else if (a[i] > pivot) {
                    int t = a[gt];
                    a[gt] = a[i];
                    a[i] = t;
                    gt--;
                } else {
                    i++;
                }
            }
            if (target < lt) {
                high = lt - 1;
            } else if (target > gt) {
                low = gt + 1;
            } else {
                answer = pivot;
                break;
            }
        }
        System.out.println(answer);
    }
