public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        int m = Integer.parseInt(sc.next());
        int[] a = new int[n];
        int[] b = new int[m];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(sc.next());
        }
        for (int i = 0; i < m; i++) {
            b[i] = Integer.parseInt(sc.next());
        }
        if (n > m) {
            int[] t = a;
            a = b;
            b = t;
            int tn = n;
            n = m;
            m = tn;
        }
        int half = (n + m + 1) / 2;
        int low = 0;
        int high = n;
        double median = 0;
        while (low <= high) {
            int i = (low + high) / 2;
            int j = half - i;
            long aLeft = i == 0 ? Long.MIN_VALUE : a[i - 1];
            long aRight = i == n ? Long.MAX_VALUE : a[i];
            long bLeft = j == 0 ? Long.MIN_VALUE : b[j - 1];
            long bRight = j == m ? Long.MAX_VALUE : b[j];
            if (aLeft <= bRight && bLeft <= aRight) {
                long leftMax = Math.max(aLeft, bLeft);
                if ((n + m) % 2 == 1) {
                    median = leftMax;
                } else {
                    median = (leftMax + Math.min(aRight, bRight)) / 2.0;
                }
                break;
            } else if (aLeft > bRight) {
                high = i - 1;
            } else {
                low = i + 1;
            }
        }
        System.out.println(String.format(Locale.US, "%.1f", median));
    }
}

