public class Main {
    static long countAtMost(int[] a, long d) {
        long count = 0;
        int i = 0;
        for (int j = 0; j < a.length; j++) {
            while ((long) a[j] - a[i] > d) {
                i++;
            }
            count += j - i;
        }
        return count;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        long k = Long.parseLong(sc.next());
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(sc.next());
        }
        Arrays.sort(a);
        long low = 0;
        long high = (long) a[n - 1] - a[0];
        while (low < high) {
            long mid = (low + high) / 2;
            if (countAtMost(a, mid) >= k) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        System.out.println(low);
    }
}
